package Controllers; import Services.CartService; import java.io.*; import javax.servlet.annotation.WebServlet; import javax.servlet.http.*;
@WebServlet("/AddToCartServlet") public class AddToCartServlet extends HttpServlet{private final CartService s=new CartService();protected void doPost(HttpServletRequest r,HttpServletResponse p)throws IOException{s.add(r.getSession(),Integer.parseInt(r.getParameter("productId")));p.sendRedirect("ViewCartServlet");}}
